class Gradebook:
    def __init__(self) -> None:
        self.assignments: dict[str, dict] = {}
        self.grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self.grades.get(student, {})

        # Collect all assignments with their effective grades
        quizzes = []
        homeworks = []

        for name, info in self.assignments.items():
            grade = student_grades.get(name, 2.0)
            weight = info["weight"]
            kind = info["kind"]

            if kind == "quiz":
                quizzes.append((name, grade, weight))
            else:
                homeworks.append((name, grade, weight))

        # Drop the lowest quiz grade if there is more than one quiz
        if len(quizzes) > 1:
            # Sort by grade ascending; drop the first element
            quizzes.sort(key=lambda item: item[1])
            quizzes = quizzes[1:]

        included = homeworks + quizzes
        total_weight = sum(weight for _, _, weight in included)

        if total_weight == 0:
            return 2.0

        weighted_sum = sum(grade * weight for _, grade, weight in included)
        return round(weighted_sum / total_weight, 2)
```

